  'Tell viewers about your channel...' => 'Ասացեք դիտողներին ձեր ալիքի մասին...',
  'Add an about section so viewers know what your channel is about.' => 'Ավելացրեք մասին բաժին, որպեսզի դիտողները իմանան, թե ինչի մասին է ձեր ալիքը:',
  'This channel has not added an about section yet.' => 'Այս ալիքը դեռ չի ավելացրել մասին բաժին:',
  'Admin' => 'Ադմին',
  'Dashboard' => 'Վահանակ',
  'Users' => 'Օգտատերեր',
  'Reports' => 'Հաշվետվություններ',
  'Support' => 'Աջակցություն',
  'Roles & Permissions' => 'Դերեր և թույլտվություններ',
  'System Settings' => 'Համակարգի կարգավորումներ',
  'Monitor platform activity, moderation, revenue, and system health.' => 'Դիտեք հարթակի գործունեությունը, չափավորությունը, եկամուտը և համակարգի առողջությունը:',
  'Manage and monitor platform users, permissions, and activity.' => 'Կառավարեք և վերահսկեք հարթակի օգտագործողներին, թույլտվությունները և գործունեությունը:',
  'Manage creators, channel performance, verification, and creator growth.' => 'Կառավարեք ստեղծողներին, ալիքի արդյունավետությունը, հաստատումը և հեղինակների աճը:',
  'Manage videos, shorts, posts, and content moderation across the platform.' => 'Կառավարեք տեսանյութերը, շորտերը, գրառումները և բովանդակության մոդերատորությունը հարթակում:',
  'Monitor live sessions, scheduling, stream health, and live moderation.' => 'Դիտեք ուղիղ եթերում նիստերը, պլանավորումը, հեռարձակման առողջությունը և ուղիղ ռեժիմը:',
  'Review flagged content, user complaints, and platform safety incidents.' => 'Դիտեք նշագրված բովանդակությունը, օգտվողների բողոքները և հարթակի անվտանգության միջադեպերը:',
  'Track revenue, payouts, subscriptions, ads, tips, and creator earnings.' => 'Հետևեք եկամուտներին, վճարումներին, բաժանորդագրություններին, գովազդին, հուշումներին և հեղինակի եկամուտներին:',
  'Analyze platform growth, viewer behavior, engagement, and content performance.' => 'Վերլուծեք հարթակի աճը, դիտողների վարքագիծը, ներգրավվածությունը և բովանդակության կատարումը:',
  'Manage support tickets, help requests, escalations, and response quality.' => 'Կառավարեք աջակցության տոմսերը, օգնության հարցումները, էսկալացիաները և պատասխանի որակը:',
  'Manage admin roles, access levels, team members, and security permissions.' => 'Կառավարեք ադմինիստրատորի դերերը, մուտքի մակարդակները, թիմի անդամներին և անվտանգության թույլտվությունները:',
  'Configure platform preferences, integrations, security, storage, and system behavior.' => 'Կարգավորեք հարթակի նախապատվությունները, ինտեգրումները, անվտանգությունը, պահեստավորումը և համակարգի վարքագիծը:',
