  'Contact Support' => 'Կապվեք աջակցության հետ',
  'Contact support for privacy, data, and account questions.' => 'Գաղտնիության, տվյալների և հաշվի հարցերի համար կապվեք աջակցության հետ:',
  'Contact us' => 'Կապվեք մեզ հետ',
  'Content rules' => 'Բովանդակության կանոններ',
  'Controls' => 'Կառավարում',
  'Cookie Category' => 'Թխվածքաբլիթների կատեգորիա',
  'Cookie Policy' => 'Cookie քաղաքականություն',
  'Copy' => 'Պատճենել',
  'Create an account, open Creator Studio, complete your channel profile, then upload or organize videos from your dashboard.' => 'Ստեղծեք հաշիվ, բացեք Creator Studio-ն, լրացրեք ձեր ալիքի պրոֆիլը, ապա վերբեռնեք կամ կազմակերպեք տեսանյութեր ձեր վահանակից:',
  'Creator and Pro features' => 'Creator և Pro առանձնահատկությունները',
  'Creator channels' => 'Ստեղծող ալիքներ',
  'Creator data' => 'Ստեղծողի տվյալները',
  'Creator profile pages, subscriptions, community posts, comments, and playlists are part of the same account and content system.' => 'Ստեղծողի պրոֆիլի էջերը, բաժանորդագրությունները, համայնքի գրառումները, մեկնաբանությունները և երգացանկերը նույն հաշվի և բովանդակության համակարգի մաս են կազմում:',
  'Creator publishing' => 'Ստեղծողի հրատարակում',
  'Creator Studio content management uses the same visibility model: public, unlisted, or private. Scheduled videos use requested visibility after release.' => 'Creator Studio-ի բովանդակության կառավարումն օգտագործում է նույն տեսանելիության մոդելը՝ հանրային, չցուցակված կամ մասնավոր: Պլանավորված տեսանյութերը թողարկումից հետո օգտագործում են պահանջված տեսանելիությունը:',
  'Creator tools' => 'Ստեղծող գործիքներ',
  'Creator uploads' => 'Ստեղծողի վերբեռնումներ',
  'Creators can upload videos, manage visibility, add thumbnails and captions, publish scheduled content, review their library, and track content from Creator Studio.' => 'Ստեղծողները կարող են վերբեռնել տեսանյութեր, կառավարել տեսանելիությունը, ավելացնել մանրապատկերներ և ենթագրեր, հրապարակել պլանավորված բովանդակություն, վերանայել իրենց գրադարանը և հետևել Creator Studio-ի բովանդակությանը:',
  'Creators must provide accurate titles, descriptions, categories, languages, thumbnails, captions, visibility, and scheduling settings. Scheduled videos are not public until their scheduled time and successful processing.' => 'Ստեղծողները պետք է տրամադրեն ճշգրիտ վերնագրեր, նկարագրություններ, կատեգորիաներ, լեզուներ, մանրապատկերներ, ենթագրեր, տեսանելիություն և ժամանակացույցի կարգավորումներ: Պլանավորված տեսանյութերը հրապարակային չեն մինչև դրանց նախատեսված ժամանակը և հաջող մշակումը:',
  'curl --request GET \\\\ --url' => 'curl --խնդրում GET \\\\ --url',
  'Current upload categories' => 'Վերբեռնման ընթացիկ կատեգորիաները',
  'Data is used to authenticate users, publish and process content, show videos and channels, personalize account preferences, prevent abuse, support moderation, provide admin analytics, and keep creator and viewer features working.' => 'Տվյալներն օգտագործվում են օգտատերերին նույնականացնելու, բովանդակությունը հրապարակելու և մշակելու, տեսանյութեր և ալիքներ ցուցադրելու, հաշվի նախապատվությունները անհատականացնելու, չարաշահումները կանխելու, մոդերատորությանը աջակցելու, ադմինիստրատորի վերլուծություն տրամադրելու և ստեղծողի և դիտողի գործառույթները շարունակելու համար:',
  'Data processed by PlayHub' => 'PlayHub-ի կողմից մշակված տվյալները',
  'Database' => 'Տվյալների բազա',
  'Platform content' => 'Տվյալների բազայի վրա հիմնված բովանդակություն',
  'Engagement such as views, likes, comments, and subscriptions.' => 'Տվյալների բազայի վրա հիմնված ներգրավվածություն, ինչպիսիք են դիտումները, հավանումները, մեկնաբանությունները և բաժանորդագրությունները:',
  'Decision' => 'Որոշում',
