  'Essential' => 'Էական',
  'Essential storage' => 'Հիմնական պահեստավորում',
  'Examples' => 'Օրինակներ',
  'Explore creators' => 'Բացահայտեք ստեղծողներին',
  'Explore videos' => 'Ուսումնասիրեք տեսանյութերը',
  'Fastest Rising' => 'Ամենաարագ աճող',
  'Feature not working' => 'Գործառույթը չի աշխատում',
  'Featured articles' => 'Առաջարկվող հոդվածներ',
  'Find answers, get support, and learn how to use PlayHub’s upload, account, creator, and admin features.' => 'Գտեք պատասխաններ, ստացեք աջակցություն և սովորեք, թե ինչպես օգտագործել PlayHub-ի իրական վերբեռնման, հաշվի, ստեղծողի և ադմինիստրատորի գործառույթները:',
  'Find practical support for account access, uploads, playback, creator tools, and moderation.' => 'Գտեք գործնական աջակցություն հաշիվ մուտք գործելու, վերբեռնումների, նվագարկման, ստեղծողի գործիքների և չափավորության համար:',
  'Find quick answers about PlayHub accounts, uploads, support tickets, privacy, and creator tools.' => 'Գտեք արագ պատասխաններ PlayHub-ի հաշիվների, վերբեռնումների, աջակցության տոմսերի, գաղտնիության և ստեղծողի գործիքների մասին:',
  'Follow' => 'Հետևեք',
  'For creators' => 'Ստեղծողների համար',
  'For viewers' => 'Դիտողների համար',
  'Frequently asked questions' => 'Հաճախակի տրվող հարցեր',
  'Functional' => 'Ֆունկցիոնալ',
  'General inquiries' => 'Ընդհանուր հարցումներ',
  'Generated' => 'Գեներացվել է',
  'Get in touch' => 'Կապվեք',
  'Get started in 3 steps' => 'Սկսեք 3 քայլով',
  'Getting Started' => 'Սկսել',
  'Getting started on PlayHub' => 'Սկսում ենք PlayHub-ում',
  'Global and remote' => 'Համաշխարհային և հեռավոր',
  'Go to Upload, choose your video file, add required details, select category and language, add a thumbnail, then publish. Large files upload in chunks.' => 'Գնացեք Վերբեռնում, ընտրեք ձեր վիդեո ֆայլը, ավելացրեք պահանջվող մանրամասները, ընտրեք կատեգորիան և լեզուն, ավելացրեք մանրապատկեր, ապա հրապարակեք: Մեծ ֆայլերը վերբեռնվում են կտորներով:',
  'Guest mode' => 'Հյուրի ռեժիմ',
  'Have a question, feedback, partnership idea, or support request? Send it through the backend form and admins will see it in the Support dashboard.' => 'Հարց, կարծիք, գործընկերության գաղափար կամ աջակցության հարցում ունե՞ք: Ուղարկեք այն backend ձևի միջոցով, և ադմինները կտեսնեն այն Աջակցության վահանակում:',
  'High priority' => 'Բարձր առաջնահերթություն',
  'How can I become a creator?' => 'Ինչպե՞ս կարող եմ ստեղծագործող դառնալ:',
  'How can we help you?' => 'Ինչպե՞ս կարող ենք օգնել ձեզ:',
  'How can we help?' => 'Ինչպե՞ս կարող ենք օգնել:',
  'How data is used' => 'Ինչպես են օգտագործվում տվյալները',
  'How do I become a creator?' => 'Ինչպե՞ս կարող եմ ստեղծագործող դառնալ:',
  'How do I report inappropriate content?' => 'Ինչպե՞ս կարող եմ զեկուցել ոչ պատշաճ բովանդակության մասին:',
  'How do I update password or two-factor authentication?' => 'Ինչպե՞ս թարմացնել գաղտնաբառը կամ երկգործոն նույնականացումը:',
  'How do I upload a video?' => 'Ինչպե՞ս վերբեռնել տեսանյութ:',
  'How do uploads work?' => 'Ինչպե՞ս են աշխատում վերբեռնումները:',
  'How is my privacy protected?' => 'Ինչպե՞ս է պաշտպանվում իմ գաղտնիությունը:',
  'How many upload languages are available?' => 'Վերբեռնման քանի՞ լեզու կա:',
  'How PlayHub uses cookies and browser storage for sessions, security, preferences, and playback.' => 'Ինչպես է PlayHub-ն օգտագործում թխուկները և դիտարկիչի պահեստը նիստերի, անվտանգության, նախապատվությունների և նվագարկման համար:',
  'How this PlayHub deployment handles account, content, activity, security, and preference data.' => 'Ինչպես է PlayHub-ի այս տեղակայումը մշակում հաշվի, բովանդակության, գործունեության, անվտանգության և նախապատվության տվյալները:',
  'How to upload your first video' => 'Ինչպես վերբեռնել ձեր առաջին տեսանյութը',
  'I need help with my account' => 'Ես օգնության կարիք ունեմ իմ հաշվի հետ կապված',
  'icon-button mini-icon' => 'պատկերակ-կոճակ մինի-պատկերակ',
  'If approved, payment is returned through the original method.' => 'Հաստատվելու դեպքում վճարումը վերադարձվում է սկզբնական եղանակով:',
  'If no paid transaction exists in the connected billing provider or platform records, there is no platform charge to refund. Refunds can only be reviewed against payment records, subscription IDs, invoices, or transaction references.' => 'Եթե ​​վճարովի գործարք չկա միացված վճարային մատակարարի կամ հարթակի գրառումներում, գումարի վերադարձի համար հարթակի վճար չկա: Գումարի վերադարձը կարող է վերանայվել միայն իրական վճարումների գրառումների, բաժանորդագրության ID-ների, հաշիվ-ապրանքագրերի կամ գործարքների հղումների հիման վրա:',
  'Integration rules' => 'Ինտեգրման կանոններ',
  'Join the future of video' => 'Միացե՛ք տեսանյութի ապագային',
  'Keeps queue and watch progress on this device.' => 'Պահում է հերթեր և դիտումների առաջընթաց այս սարքում:',
  'Playback Queue' => 'Playback Queue',
  'Keeps your temporary playback queue on this device.' => 'Keeps your temporary playback queue on this device.',
  'Watch Progress' => 'Watch Progress',
  'Saves continue-watching progress for signed-in users.' => 'Saves continue-watching progress for signed-in users.',
  'video_watch_progress' => 'video_watch_progress',
  'Languages' => 'Լեզուներ',
  'Large uploads use upload sessions: create a session, send numbered chunks, then complete the session with title, description, category, language, visibility, schedule, thumbnail, captions, and monetization fields.' => 'Խոշոր վերբեռնումները օգտագործում են վերբեռնման սեսիաներ. ստեղծեք նիստ, ուղարկեք համարակալված հատվածներ, այնուհետև ավարտեք նիստը վերնագրի, նկարագրության, կատեգորիայի, լեզվի, տեսանելիության, ժամանակացույցի, մանրապատկերների, ենթագրերի և դրամայնացման դաշտերով:',
  'Last updated: June 29, 2026' => 'Վերջին թարմացումը՝ 2026 թվականի հունիսի 29',
  'Legal' => 'Իրավական',
  'Live & scheduling' => 'Ուղիղ եթեր և ժամանակացույց',
  'Live counts' => 'Ուղիղ եթերը հաշվում է',
  'Live counts are loaded from the backend.' => 'Ուղիղ եթերը բեռնվում են հետնամասից:',
  'Current' => 'Կենդանի տվյալների բազա',
  'Live endpoint groups' => 'Կենդանի վերջնակետային խմբեր',
  'Loading categories...' => 'Տվյալների բազայից կատեգորիաների բեռնում...',
  'Loading category activity...' => 'Կատեգորիայի գործունեությունը բեռնվում է...',
  'Loading creator and content counts.' => 'Բեռնվում է ստեղծողի և բովանդակության թիվը:',
  'Loading creator channels...' => 'Ստեղծողի ալիքների բեռնում տվյալների բազայից...',
  'Loading endpoints' => 'Բեռնվում են վերջնակետերը',
  'Loading live API capabilities from the backend.' => 'Ուղիղ API-ի հնարավորությունների բեռնում հետնամասից:',
  'Loading live API metadata...' => 'Ուղիղ API-ի մետատվյալների բեռնում...',
  'Loading live PlayHub platform data from the backend...' => 'PlayHub հարթակի ուղիղ տվյալների բեռնում հետնամասից...',
  'Loading routes' => 'Երթուղիների բեռնում',
  'Loading taxonomy metadata.' => 'Տաքսոնոմիայի մետատվյալների բեռնում:',
  'Loading upload configuration.' => 'Վերբեռնման կոնֆիգուրացիան բեռնվում է:',
  'Loading...' => 'Բեռնվում է...',
  'Local storage' => 'Տեղական պահեստավորում',
  'Manage language, theme, security, and notification settings from your account.' => 'Կառավարեք լեզուն, թեման, անվտանգությունը և ծանուցումների կարգավորումները ձեր հաշվից:',
  'Max upload' => 'Առավելագույն վերբեռնում',
  'Media and analytics storage' => 'Մեդիա և վերլուծական պահեստավորում',
  'Messages submitted on the Contact page are saved and shown in the admin Support dashboard as contact tickets.' => 'Կոնտակտային էջում ներկայացված հաղորդագրությունները պահվում են տվյալների բազայում և ցուցադրվում են ադմինիստրատորի Աջակցության վահանակում՝ որպես կոնտակտային տոմսեր:',
  'Moderation help' => 'Չափավորության օգնություն',
  'More⌄' => 'Ավելին⌄',
  'Need help?' => 'Օգնությա՞ն է պետք:',
  'Need more help?' => 'Ավելի շատ օգնության կարիք ունե՞ք:',
  'No answers found for this topic and search.' => 'Այս թեմայի և որոնման համար պատասխաններ չեն գտնվել:',
  'No category activity found yet.' => 'Կատեգորիայի գործունեություն դեռ չի գտնվել:',
  'No creator channels found yet.' => 'Ստեղծողի ալիքներ դեռ չեն գտնվել:',
  'No upload categories are configured.' => 'Վերբեռնման կատեգորիաներ կազմաձևված չեն:',
  'Non-refundable cases' => 'Չվերադարձվող դեպքեր',
  'noopener,noreferrer' => 'ոչ բացիչ, ոչ հղում',
  'Normal priority' => 'Սովորական առաջնահերթություն',
  'Not available' => 'Հասանելի չէ',
  'Not provided' => 'Չի տրամադրվում',
  'Official contact addresses, billing contacts, and external support channels should be configured by the PlayHub site administrator for this deployment. This page intentionally does not display unverified email addresses.' => 'Պաշտոնական կոնտակտային հասցեները, վճարային կոնտակտները և արտաքին աջակցության ուղիները պետք է կազմաձևվեն PlayHub կայքի ադմինիստրատորի կողմից այս տեղակայման համար: Այս էջը միտումնավոր չի ցուցադրում չստուգված էլփոստի հասցեներ:',
  'On this page' => 'Այս էջում',
  'Open Help Center' => 'Բացեք Օգնության կենտրոնը',
  'Open settings' => 'Բացեք կարգավորումները',
  'Open Settings, go to Security, then use the password or two-factor dialog. Two-factor delivery supports email or phone when configured.' => 'Բացեք Կարգավորումները, անցեք Անվտանգություն, ապա օգտագործեք գաղտնաբառը կամ երկգործոն երկխոսությունը: Երկգործոն առաքումն աջակցում է էլ.փոստին կամ հեռախոսին, երբ կազմաձևված է:',
  'Operational snapshot' => 'Գործառնական պատկեր',
  'Optional, but recommended' => 'Ընտրովի, բայց խորհուրդ է տրվում',
  'Other' => 'Այլ',
  'Partnerships, press, and platform operations.' => 'Գործընկերություններ, մամուլի և հարթակի գործառնություններ:',
  'Payment help' => 'Վճարման օգնություն',
  'Platform' => 'Հարթակ',
  'Playback' => 'Նվագարկում',
  'Playback progress, watch-later state, likes, comments, subscriptions, notifications, and admin analytics are saved when linked to authenticated platform features.' => 'Նվագարկման առաջընթացը, ավելի ուշ դիտման վիճակը, հավանումները, մեկնաբանությունները, բաժանորդագրությունները, ծանուցումները և ադմինիստրատորի վերլուծությունը պահվում են տվյալների բազայում, երբ կապված են հաստատված հարթակի գործառույթների հետ:',
  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'Նվագարկումը, մեկնաբանությունները, հավանումները, ավելի ուշ դիտելը, բաժանորդագրությունները, ծանուցումները, հաղորդագրությունները, երգացանկերը և լեզվի կարգավորումները հասանելի են հիմնական նավիգացիայի և հաշվի ընտրացանկի միջոցով:',
  'PlayHub' => 'PlayHub',
  'PlayHub is a video platform for uploading, watching, scheduling, managing, and moderating creator content from one account.' => 'PlayHub-ը վիդեո հարթակ է մեկ հաշվից ստեղծողի բովանդակությունը վերբեռնելու, դիտելու, պլանավորելու, կառավարելու և վարելու համար:',
  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub-ը վիդեո հարթակ է, որն աշխատում է այս տեղակայման վրա, որը ստեղծվել է ստեղծողների, դիտողների, համայնքների և հարթակի օպերատորների համար:',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub-ը տրամադրում է ստեղծողների ալիքներ, տեսանյութերի վերբեռնումներ, պլանավորված հրապարակումներ, բաժանորդագրություններ, մեկնաբանություններ, երգացանկեր, ավելի ուշ դիտումներ, կենդանի բովանդակության էջեր և կառավարման գործիքներ մեկ հարթակից:',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub-ն օգտագործում է էական թխուկներ և բրաուզերի պահեստ՝ մուտքի աշխատաշրջանների, API-ի նույնականացման, CSRF/անվտանգության վարքագծի, լեզվի ընտրության, թեմայի ընտրության, հաշվի ցանկի վիճակի և հավելվածի աշխատանքի համար անհրաժեշտ այլ գործառույթների համար:',
  'playhub_language, theme' => 'playhub_language, թեմա',
  'Popular questions' => 'Հանրաճանաչ հարցեր',
  'Preference storage' => 'Նախապատվությունների պահեստավորում',
  'Privacy Policy' => 'Գաղտնիության քաղաքականություն',
  'Privacy, cookie, account security, support messages, and moderation data are handled through the policies and backend records connected to PlayHub.' => 'Գաղտնիությունը, թխուկները, հաշվի անվտանգությունը, աջակցության հաղորդագրությունները և հսկողության տվյալները մշակվում են PlayHub-ին միացված քաղաքականության և հետին պլանի գրառումների միջոցով:',
  'Profile, login, security, and settings help.' => 'Օգնում են պրոֆիլը, մուտքը, անվտանգությունը և կարգավորումները:',
  'Profile, security, and preferences.' => 'Պրոֆիլ, անվտանգություն և նախապատվություններ:',
  'Public API route' => 'Հանրային API երթուղի',
  'Public JSON endpoints include /api/health for deployment status and /api/upload-options for upload categories, languages, limits, chunk size, and trending tags.' => 'Հանրային JSON վերջնակետերը ներառում են /api/health for deployment կարգավիճակը և /api/upload-options վերբեռնման կատեգորիաների, լեզուների, սահմանաչափերի, կտորի չափի և տենդենցային պիտակների համար:',
  'Public REST API' => 'Հանրային REST API',
  'Published videos' => 'Հրապարակված տեսանյութեր',
  'Purchase date' => 'Գնման ամսաթիվը',
  'purchaseDate' => 'գնման ամսաթիվը',
  'Purpose' => 'Նպատակը',
  'Questions about privacy?' => 'Հարցեր գաղտնիության մասին:',
  'Quick links' => 'Արագ հղումներ',
  'Rate limits' => 'Գնահատման սահմանները',
  'Read upload options' => 'Կարդացեք վերբեռնման տարբերակները',
  'Platform capabilities' => 'Իրական հարթակի հնարավորություններ',
  'Platform overview' => 'Իրական հարթակի տվյալներ',
  'Reason' => 'Պատճառը',
  'Recent creator channels' => 'Ստեղծողների վերջին ալիքները',
  'Refund' => 'Փոխհատուցում',
  'Refund and paid feature guidance.' => 'Գումարի վերադարձ և վճարովի գործառույթի ուղեցույց:',
  'Refund handling for paid PlayHub features depends on billing records attached to this deployment.' => 'PlayHub-ի վճարովի գործառույթների համար գումարի վերադարձը կախված է այս տեղաբաշխմանը կցված իրական հաշվարկային գրառումներից:',
  'Refund handling is tied to billing records and administrator review. If billing is not configured for this deployment, there is no platform charge to refund.' => 'Գումարի վերադարձը կապված է իրական հաշվարկային գրառումների և ադմինիստրատորի վերանայման հետ: Եթե ​​բիլինգը կազմաձևված չէ այս տեղաբաշխման համար, պլատֆորմի համար վճար չի գանձվում:',
  'Refund issued' => 'Տրված է գումարի վերադարձ',
  'Refund page' => 'Փոխհատուցման էջ',
  'Refund Policy' => 'Փոխհատուցման քաղաքականություն',
  'Refund reason' => 'Փոխհատուցման պատճառ',
  'Refund request' => 'Փոխհատուցման հարցում',
  'Refund request process' => 'Փոխհատուցման հայտի գործընթաց',
  'refund-dialog contact-message-form' => 'վերադարձ-երկխոսություն կոնտակտային-հաղորդագրություն-ձև',
  'Registered users' => 'Գրանցված օգտվողներ',
  'Related legal pages' => 'Առնչվող իրավական էջեր',
  'Report a problem' => 'Հաղորդել խնդրի մասին',
  'Reports, moderation, and privacy.' => 'Հաշվետվություններ, մոդերատորություն և գաղտնիություն:',
  'Reports, moderation, privacy, and community safety.' => 'Հաշվետվություններ, չափավորություն, գաղտնիություն և համայնքի անվտանգություն:',
  'Request a refund' => 'Պահանջել փոխհատուցում',
  'Required' => 'Պահանջվում է',
  'Required for login, security, and app routing.' => 'Պահանջվում է մուտքի, անվտանգության և հավելվածների երթուղղման համար:',
  'Response targets' => 'Արձագանքման թիրախներ',
  'Retention and access' => 'Պահպանում և մուտք',
  'Review privacy and cookie details for this deployment.' => 'Դիտեք գաղտնիության և թխուկների մանրամասները այս տեղակայման համար:',
  'Rules for using this PlayHub deployment as a viewer, creator, or administrator.' => 'PlayHub-ի այս տեղակայումը որպես դիտող, ստեղծող կամ ադմինիստրատոր օգտագործելու կանոններ:',
  'Safety' => 'Անվտանգություն',
  'Safety / technical' => 'Անվտանգություն / տեխնիկական',
  'Safety and content reports' => 'Անվտանգության և բովանդակության հաշվետվություններ',
  'Safety or report' => 'Անվտանգություն կամ հաշվետվություն',
  'Sample endpoints' => 'Վերջնական կետերի նմուշ',
  'sample endpoints loaded' => 'բեռնված վերջնական կետերի նմուշը',
  'Schedule video' => 'Պլանավորեք տեսանյութը',
  'Scheduled video release and reminders.' => 'Պլանավորված տեսանյութի թողարկում և հիշեցումներ:',
  'Scheduled videos' => 'Պլանավորված տեսանյութեր',
  'Scheduling a video release' => 'Տեսահոլովակի թողարկման պլանավորում',
  'Search for answers...' => 'Փնտրեք պատասխաններ...',
  'Search help articles, topics, or questions...' => 'Որոնեք օգնության հոդվածներ, թեմաներ կամ հարցեր...',
  'Select a reason' => 'Ընտրեք պատճառ',
  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'Ընտրեք մեկ կամ մի քանի վիդեո ֆայլ, մուտքագրեք պահանջվող մանրամասները, ընտրեք կատեգորիա և լեզուն, ավելացրեք մանրապատկեր, ընտրեք տեսանելիությունը և հրապարակեք: Խոշոր ֆայլերը վերբեռնվում են կտորներով՝ նախքան սերվերի մշակումը սկսելը:',
  'Send a message and it will be saved for admins.' => 'Ուղարկեք հաղորդագրություն և այն կպահվի ադմինիստրատորների համար:',
  'Send billing details to admin support for review.' => 'Ուղարկեք վճարման մանրամասները ադմինիստրատորի աջակցությանը վերանայման համար:',
  'Send message' => 'Ուղարկել հաղորդագրություն',
  'Send order details through the refund popup.' => 'Ուղարկեք պատվերի մանրամասները վերադարձման պատուհանի միջոցով:',
  'Send us a message' => 'Ուղարկեք մեզ հաղորդագրություն',
  'Sending...' => 'Ուղարկում...',
  'Server configured' => 'Սերվերը կազմաձևված է',
  'server records' => 'սերվերի գրառումները',
  'Service operation' => 'Սպասարկման շահագործում',
  'session, token' => 'նիստ, նշան',
  'Settings and login' => 'Կարգավորումներ և մուտք',
  'Short summary' => 'Կարճ ամփոփում',
  'Sign in and use Settings for account, profile, password, notification, privacy, and creator preferences. Creator upload and content issues should include the video title, channel, browser, and any processing error shown on the upload page.' => 'Մուտք գործեք և օգտագործեք Կարգավորումները հաշվի, պրոֆիլի, գաղտնաբառի, ծանուցումների, գաղտնիության և ստեղծողի նախապատվությունների համար: Ստեղծողի վերբեռնման և բովանդակության հետ կապված խնդիրները պետք է ներառեն տեսանյութի անվանումը, ալիքը, դիտարկիչը և վերբեռնման էջում ցուցադրված ցանկացած մշակման սխալ:',
  'Sign in for account support' => 'Մուտք գործեք հաշվի աջակցության համար',
  'Signed in' => 'Մուտք գործեց',
  'Start uploading' => 'Սկսեք վերբեռնել',
  'Still can’t find an answer?' => 'Դեռ չե՞ք կարողանում պատասխան գտնել:',
  'Stored for admins' => 'Պահպանվում է ադմինիստրատորների համար',
  'Stores language, theme, and interface preferences.' => 'Պահպանում է լեզուն, թեման և ինտերֆեյսի նախապատվությունները:',
  'Studio, playlists, analytics, channels.' => 'Ստուդիա, երգացանկ, վերլուծություն, ալիքներ:',
  'Submit a billing or refund message to admin support.' => 'Ադմինիստրատորի աջակցությանն ուղարկեք վճարման կամ վերադարձման հաղորդագրություն:',
  'Submit refund request' => 'Ներկայացրեք վերադարձման հարցում',
  'Submit request' => 'Ներկայացրեք հարցումը',
  'Subscription cancellation' => 'Բաժանորդագրության չեղարկում',
  'Support dashboard' => 'Աջակցման վահանակ',
  'System status' => 'Համակարգի կարգավիճակը',
  'Table' => 'Աղյուսակ',
  'Taxonomies' => 'Տաքսոնոմիաներ',
  'Technical issue' => 'Տեխնիկական խնդիր',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'Տեխնիկական նշումներ ընթացիկ PlayHub API-ի հետ ինտեգրվելու և վերբեռնման աշխատանքային հոսքի համար:',
  'Tell us more about your question or request...' => 'Պատմեք մեզ ավելին ձեր հարցի կամ խնդրանքի մասին...',
  'Terms of Use' => 'Օգտագործման պայմաններ',
  'The configured' => 'Կազմաձևվածը',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'Մշակողի էջը միացված է կենդանի Laravel-ի հետին պլանին. երթուղիների գույքագրումը, տվյալների բազայի հաշվարկները, վերբեռնման սահմանափակումները և հարթակի մետատվյալները բեռնված են /api/developers-ից:',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'Frontend-ը պահպանում է այնպիսի նախապատվություններ, ինչպիսիք են ընտրված լեզուն, թեման, նվագարկման հերթը, դիտման առաջընթացը և ինտերֆեյսի վիճակը, որպեսզի փորձը մնա հետևողական էջերի նավիգացիայի և վերաբեռնումների ընթացքում:',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'Մշակման աշխատանքը կոդավորում է կատարումները, անհրաժեշտության դեպքում ստեղծում մանրապատկերներ, պահում են ենթագրերը և նշում պատրաստի տեսանյութերը, երբ մշակումն ավարտվի: Ապագա պլանավորված տեսանյութերը մնում են գաղտնի, քանի դեռ ժամանակացույցը չի հրապարակել դրանք:',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'Վերբեռնման համակարգը հիմնված է տվյալների բազայի վրա, աջակցում է API-ի կատեգորիաները և լեզուները, մշակում է վերբեռնված տեսանյութերը, պահում մանրապատկերներն ու ենթագրերը և պլանավորված բովանդակությունը գաղտնի է պահում մինչև դրա թողարկման ժամանակը:',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'Այս էջը բացատրում է, թե ինչպես է PlayHub-ն օգտագործում թխուկները և դիտարկիչի պահեստը նիստերի, անվտանգության, նախապատվությունների, նվագարկման և վավերացված գործառույթների համար:',
  'Ticket source' => 'Տոմսերի աղբյուրը',
  'Top content categories' => 'Բովանդակության լավագույն կատեգորիաները',
  'Topic' => 'Թեմա',
  'Transaction / invoice' => 'Գործարք / հաշիվ-ապրանքագիր',
  'Transaction / invoice ID' => 'Գործարքի / հաշիվ-ապրանքագրի ID',
  'Unable to send message.' => 'Հնարավոր չէ ուղարկել հաղորդագրություն:',
  'Unable to submit refund request.' => 'Հնարավոր չէ վերադարձման հարցում ուղարկել:',
  'Understanding admin support tickets' => 'Հասկանալով ադմինիստրատորի աջակցության տոմսերը',
  'Upload and processing help' => 'Վերբեռնման և մշակման օգնություն',
  'Upload chunks' => 'Վերբեռնեք կտորներ',
  'Upload issues' => 'Վերբեռնման խնդիրներ',
  'Upload languages' => 'Վերբեռնեք լեզուներ',
  'Upload limit' => 'Վերբեռնման սահմանափակում',
  'Upload options' => 'Վերբեռնման ընտրանքներ',
  'Upload or processing' => 'Վերբեռնում կամ մշակում',
  'Upload page' => 'Վերբեռնել էջը',
  'Upload pipeline' => 'Վերբեռնել խողովակաշարը',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'Վերբեռնեք, դիտեք, բաժանորդագրվեք, վերահսկեք և ստեղծեք PlayHub-ի ուղիղ տվյալներ:',
  'Uploaded videos' => 'Վերբեռնված տեսանյութեր',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'Վերբեռնված տեսանյութերը կոդավորված են նվագարկվող վերափոխումների մեջ: Մշակման ժամանակը կախված է ֆայլի չափից, տևողությունից, սերվերի բեռնվածությունից և հերթի կարգավիճակից: Վերբեռնման էջը և Creator Studio-ն ցույց են տալիս տեսագրությունից մշակման իրական կարգավիճակը:',
  'Uploads, scheduling, and processing are available.' => 'Հասանելի են վերբեռնումներ, պլանավորում և մշակում:',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'Ստեղծողի աշխատանքային հոսքերի համար օգտագործեք /api/տեսանյութերը, ալիքի վերջնակետերը և վավերացված երթուղիները:',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'Օգտագործեք ներկառուցված հաշվետվությունների գործողությունները տեսանյութերի և մեկնաբանությունների համար, որպեսզի ադմինիստրատորները ստանան բովանդակության ճշգրիտ հղումը: Ադմինիստրատորի վահանակի էջերն օգտագործում են տվյալների բազայի կենդանի տվյալների օգտատերերի, բովանդակության, հաշվետվությունների, դրամայնացման, վերլուծության, աջակցության, դերերի և համակարգի կարգավորումների համար:',
  'Use Contact Us' => 'Օգտագործեք Կապ մեզ հետ',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'Օգտագործեք JSON սովորական API հարցումների համար և FormData ֆայլերի վերբեռնման համար: Մի շրջանցեք վավերացումը. կատեգորիաները և լեզուները տվյալների բազայի նույնացուցիչներն են, տեսանելիությունը սահմանափակված է հանրային, չցուցակված կամ մասնավորով, իսկ ենթագրերն ընդունում են SRT, VTT կամ TXT ֆայլեր:',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'Օգտագործեք Կարգավորումները՝ ձեր պրոֆիլը, անվտանգությունը, գաղտնաբառը, երկու գործոնով առաքումը, սարքերը, նախապատվությունները և ծանուցման ընտրանքները թարմացնելու համար: Եթե ​​չեք կարող մուտք գործել ձեր հաշիվ, օգտագործեք մուտքի հոսքը և տրամադրեք հաշվի էլ.փոստը կայքի ադմինիստրատորին:',
  'Use the contact form' => 'Օգտագործեք կոնտակտային ձևը',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'Օգտագործեք զեկույցի գործողությունները տեսանյութերի, մեկնաբանությունների և համայնքի գրառումների վրա, որպեսզի ադմինիստրատորները ստանան բովանդակության ճշգրիտ հղումը:',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'Օգտագործեք հաշվետվության գործողությունները տեսանյութերի, մեկնաբանությունների և համայնքի գրառումների վրա, երբ բովանդակությունը կարող է խախտել հարթակի կանոնները: Այս հաշվետվությունները կապված են իրական բովանդակության գրառումների հետ և ավելի լավն են, քան ընդհանուր հաղորդագրությունը, քանի որ ադմինիստրատորները կարող են վերանայել ճշգրիտ նյութը:',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'Օգտագործեք ճիշտ PlayHub ալիքը՝ հաշվի օգնության, բովանդակության հաշվետվությունների, տեխնիկական խնդիրների և ադմինիստրատորի հարցումների համար:',
  'Video categories' => 'Տեսանյութերի կատեգորիաներ',
  'Video for everyone. Built for creators and viewers.' => 'Տեսանյութ բոլորի համար. Կառուցված իրական հարթակի տվյալներից:',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'Տեսանյութերի վերբեռնման, ժամանակացույցի, մանրապատկերների և մշակման հետ կապված խնդիրներ:',
  'Videos, thumbnails, captions, processing.' => 'Տեսանյութեր, մանրապատկերներ, ենթագրեր, մշակում:',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'Դիտողները կարող են դիտել կատեգորիաները, որոնել տեսանյութեր, դիտել բովանդակություն, բաժանորդագրվել ալիքներին, պահպանել տեսանյութեր՝ ավելի ուշ դիտելու համար, մեկնաբանել, ստանալ ծանուցումներ և կառավարել լեզվի և մատչելիության նախապատվությունները:',
  'Viewing and community help' => 'Դիտում և համայնքի օգնություն',
  'Waiting for backend endpoint inventory.' => 'Սպասում է հետնամասի վերջնական կետի գույքագրմանը:',
  'We’re here to help.' => 'Մենք այստեղ ենք օգնելու համար:',
  'What is PlayHub?' => 'Ինչ է PlayHub-ը:',
  'What PlayHub does' => 'Ինչ է անում PlayHub-ը',
  'Where do contact messages go?' => 'Որտե՞ղ են գնում կոնտակտային հաղորդագրությունները:',
  'Why is my video still processing?' => 'Ինչո՞ւ է իմ տեսանյութը դեռ մշակվում:',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'Այո՛։ Օգտագործեք հայրենի ժամանակացույցի ամսաթիվը և ժամը դաշտը վերբեռնման էջում: Backend-ը պահում է scheduled_at, մշակում է տեսանյութը, այն գաղտնի է պահում, քանի դեռ ամսաթիվն ապագայում է, և թողարկում է այն, երբ Laravel-ի ժամանակացույցն աշխատում է նախատեսված ժամանակից հետո:',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'Այո՛։ Օգտագործեք հայրենի ժամանակացույցի դաշտը Վերբեռնման վրա: Backend-ը պահում է scheduled_at և թողարկում է տեսանյութը մշակումից հետո, երբ հասնում է ժամանակացույցի ժամանակը:',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'Դուք դիտում եք որպես հյուր: Մուտք գործեք՝ հաշվի հատուկ գործիքներ մուտք գործելու համար:',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'Դուք պատասխանատու եք ձեր հաշվի հավատարմագրերի, պրոֆիլի գործունեության, վերբեռնված բովանդակության, մեկնաբանությունների, հաղորդագրությունների և ձեր հաշվից կատարվող ցանկացած ստեղծողի կամ ադմինիստրատորի գործողությունների համար: Օգտագործեք ուժեղ գաղտնաբառեր և պահպանեք երկու գործոնով առաքման մեթոդները:',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'Դուք կարող եք մաքրել բրաուզերի թխուկները և տեղային պահեստը ձեր դիտարկիչի կարգավորումներում: Հիմնական պահեստը մաքրելը կարող է դուրս գալ, վերակայել լեզվի/թեմայի նախապատվությունները, հեռացնել տեղական նվագարկման վիճակը և պահանջել նորից մուտք գործել:',
  'You receive a response by email.' => 'Դուք պատասխան եք ստանում էլեկտրոնային փոստով:',
  'You’re in control' => 'Դուք վերահսկում եք',
  'Your choices' => 'Ձեր ընտրությունները',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'Ձեր հաղորդագրությունը պահվում է անմիջապես կայքի հետնամասում և հայտնվում է Աջակցության տակ գտնվող ադմինիստրատորի վահանակում:',
  'Your support' => 'Ձեր աջակցությունը',
  'Watch video' => 'Դիտեք տեսանյութը',
  'Copy link' => 'Պատճենել հղումը',
  'View creator' => 'Դիտել ստեղծողին',
  'Remove from playlist' => 'Հեռացնել երգացանկից',
  'Removing videos from playlists is not available here yet.' => 'Տեսացանկերից տեսանյութեր հեռացնելն այստեղ դեռ հասանելի չէ:',
  'Create New Playlist' => 'Ստեղծեք նոր երգացանկ',
  'Organize your videos into a playlist' => 'Կազմակերպեք ձեր տեսանյութերը երգացանկի մեջ',
  'Playlist Name' => 'Երգացանկի անվանումը',
  'e.g. Travel Vlogs 2025' => 'օր. Ճամփորդական վլոգներ 2025',
  '(optional)' => '(ըստ ցանկության)',
  'What’s this playlist about?' => 'Ինչի՞ մասին է այս երգացանկը:',
  'Select Color' => 'Ընտրեք Գույնը',
  'This color will represent your playlist' => 'Այս գույնը կներկայացնի ձեր երգացանկը',
  'Anyone can view this playlist' => 'Բոլորը կարող են դիտել այս տեսացանկը',
  'Only you can view this playlist' => 'Միայն դուք կարող եք դիտել այս երգացանկը',
  'Anyone with the link can view' => 'Բոլորը, ովքեր ունեն հղումը, կարող են դիտել',
  'Add to Playlist' => 'Ավելացնել երգացանկին',
  'Add videos to this playlist now' => 'Այժմ ավելացրեք տեսանյութեր այս երգացանկում',
  'Search videos to add...' => 'Որոնեք տեսանյութեր՝ ավելացնելու համար...',
