  'Tip' => 'Հուշում',
  'Use playlists to organize your content and make it easier for your audience to discover more videos.' => 'Use playlists to organize your content and make it easier for your audience to discover more videos.',
  'Unable to create playlist.' => 'Չհաջողվեց ստեղծել երգացանկ:',
