  'Your playlists' => 'Ձեր երգացանկերը',
  'Create your first playlist to organize videos from your channel and saved library.' => 'Ստեղծեք ձեր առաջին երգացանկը՝ ձեր ալիքից և պահված գրադարանից տեսանյութեր կազմակերպելու համար:',
  'Loading playlists...' => 'Տեսացանկերի բեռնում...',
  'No description has been added for this playlist yet.' => 'Այս տեսացանկի համար դեռ նկարագրություն չի ավելացվել:',
  'Updated' => 'Թարմացվել է',
