  'No videos match this playlist search.' => 'Տեսացանկի այս որոնմանը համապատասխան տեսանյութեր չկան:',
  'About this playlist' => 'Այս տեսացանկի մասին',
  'This playlist belongs to your PlayHub account.' => 'Այս երգացանկը օգտագործում է իրական երգացանկի ձայնագրություններ ձեր PlayHub հաշվից:',
  'Playlist stats' => 'Երգացանկի վիճակագրություն',
