  'Update playlist details and cover' => 'Թարմացրեք երգացանկի մանրամասները և շապիկը',
  'Playlist updated.' => 'Երգացանկը թարմացվել է:',
  'Save playlist' => 'Պահպանել երգացանկը',
  'Playlist cover' => 'Երգացանկի շապիկ',
  'Cover selected' => 'Ընտրված է շապիկը',
