  'Growth actions' => 'Աճի գործողություններ',
  'Based on your channel data' => 'Ձեր ալիքի տվյալների հիման վրա',
  'Publish consistently' => 'Հետևողականորեն հրապարակեք',
  'Upload your first video and give viewers a clear reason to subscribe.' => 'Վերբեռնեք ձեր առաջին տեսանյութը և դիտողներին բաժանորդագրվելու հստակ պատճառ տվեք:',
  'Use Shorts for discovery' => 'Օգտագործեք Shorts բացահայտման համար',
  'Keep testing quick hooks and link viewers to longer videos.' => 'Շարունակեք փորձարկել արագ կեռիկներ և կապեք դիտողներին ավելի երկար տեսանյութերի հետ:',
  'Create short vertical videos to reach viewers who have not found your channel yet.' => 'Ստեղծեք կարճ ուղղահայաց տեսանյութեր՝ հասնելու այն դիտողներին, ովքեր դեռ չեն գտել ձեր ալիքը:',
  'Create short' => 'Ստեղծել կարճ',
  'Turn comments into loyalty' => 'Մեկնաբանությունները վերածեք հավատարմության',
  'Reply to recent comments and turn viewers into returning fans.' => 'Պատասխանեք վերջին մեկնաբանություններին և դիտողներին դարձրեք վերադարձող երկրպագուներ:',
  'Ask a question in your next upload and reply quickly when comments arrive.' => 'Հարց տվեք ձեր հաջորդ վերբեռնման ժամանակ և արագ պատասխանեք, երբ մեկնաբանությունները հասնում են:',
  'View comments' => 'Դիտել մեկնաբանությունները',
  'Improve public reach' => 'Բարելավել հանրային հասանելիությունը',
  'Keep strong videos visible and refresh weak titles.' => 'Տեսանելի պահեք ուժեղ տեսանյութերը և թարմացրեք թույլ վերնագրերը:',
  'Explore tools' => 'Ուսումնասիրեք գործիքները',
  'Open the right workflow fast' => 'Արագ բացեք ճիշտ աշխատանքային հոսքը',
  'Upload planner' => 'Վերբեռնման պլանավորող',
  'Start a new upload with titles, tags, visibility, and thumbnail steps.' => 'Սկսեք նոր վերբեռնում վերնագրերով, պիտակներով, տեսանելիությամբ և մանրապատկերների քայլերով:',
  'Shorts studio' => 'Շորտերի ստուդիա',
  'Create short videos for faster discovery and mobile viewers.' => 'Ստեղծեք կարճ տեսանյութեր՝ ավելի արագ հայտնաբերելու և բջջային դիտողների համար:',
  'Content manager' => 'Բովանդակության կառավարիչ',
  'Review visibility, monetization, comments, and performance in one place.' => 'Դիտեք տեսանելիությունը, դրամայնացումը, մեկնաբանությունները և արդյունավետությունը մեկ վայրում:',
  'Analytics review' => 'Վերլուծության վերանայում',
  'Track views, likes, comments, publishing status, and trends.' => 'Հետևեք դիտումներին, հավանումներին, մեկնաբանություններին, հրապարակման կարգավիճակին և միտումներին:',
  'Channel profile' => 'Ալիքի պրոֆիլը',
  'Update your bio, channel details, and public creator presence.' => 'Թարմացրեք ձեր կենսագրությունը, ալիքի մանրամասները և հեղինակի ներկայությունը հրապարակային:',
  'Audience building' => 'Հանդիսատեսի շենք',
  'Study subscribers, comments, and what viewers respond to most.' => 'Ուսումնասիրեք բաժանորդները, մեկնաբանությունները և այն, ինչին ամենաշատն են արձագանքում դիտողները:',
  'Top content to learn from' => 'Լավագույն բովանդակություն, որտեղից կարելի է սովորել',
  'Upload videos to unlock performance lessons.' => 'Վերբեռնեք տեսանյութեր՝ արդյունավետության դասերը բացելու համար:',
  'Tips to reach more viewers' => 'Ավելի շատ դիտողների հասնելու խորհուրդներ',
  'Creator checklist' => 'Ստեղծողի ստուգաթերթ',
  'Hook viewers in the first 3 seconds' => 'Կեռացրեք դիտողներին առաջին 3 վայրկյանում',
  'Open with the result, conflict, or visual payoff before adding context.' => 'Բացեք արդյունքը, կոնֆլիկտը կամ տեսողական օգուտը, նախքան համատեքստ ավելացնելը:',
  'Make titles searchable' => 'Վերնագրերը դարձնել որոնելի',
  'Use the exact words viewers would type, then keep the promise in the video.' => 'Օգտագործեք այն բառերը, որոնք դիտողները կմուտքագրեն, ապա կատարեք տեսանյութի խոստումը:',
  'Convert shorts into sessions' => 'Փոխարկեք շորտեր սեսիաների',
  'Pin a comment or description link from each short to a related full video.' => 'Ամրացրեք մեկնաբանության կամ նկարագրության հղում յուրաքանչյուր կարճից համապատասխան ամբողջական տեսանյութին:',
  'Refresh underperforming uploads' => 'Թարմացրեք թերակատարվող վերբեռնումները',
  'Update thumbnails and titles after you have enough impressions to compare.' => 'Թարմացրեք մանրապատկերներն ու վերնագրերը համեմատելու համար բավականաչափ տպավորություններ ունենալուց հետո:',
  'Upload source' => 'Վերբեռնման աղբյուրը',
  'Choose a local video file or import a public video from an enabled provider.' => 'Ընտրեք տեղական վիդեո ֆայլ կամ ներմուծեք հանրային տեսանյութ միացված մատակարարից:',
  'Local upload' => 'Տեղական վերբեռնում',
  'Import from URL' => 'Ներմուծում URL-ից',
  'Import video from URL' => 'Ներմուծեք տեսանյութը URL-ից',
  'Select an enabled service and paste a public video URL. PlayHub will import it into the normal processing queue.' => 'Ընտրեք միացված ծառայություն և տեղադրեք հանրային տեսանյութի URL: PlayHub-ը կներմուծի այն նորմալ մշակման հերթում:',
  'Service' => 'Ծառայություն',
  'Video URL' => 'Տեսանյութի URL',
  'Direct video URL' => 'Ուղիղ տեսանյութի URL',
  'YouTube' => 'YouTube',
  'Vimeo' => 'Vimeo',
  'Dailymotion' => 'Dailymotion',
  'Imports a public MP4, MOV, WEBM, MKV, AVI, or M4V file URL.' => 'Ներմուծում է հանրային MP4, MOV, WEBM, MKV, AVI կամ M4V ֆայլի URL:',
  'Requires a downloader command such as yt-dlp for media import.' => 'Մեդիա ներմուծման համար պահանջում է ներբեռնիչի հրաման, ինչպիսին է yt-dlp-ը:',
  'Import queue' => 'Ներմուծման հերթ',
  'Generated after import' => 'Ստեղծվել է ներմուծումից հետո',
  'A thumbnail is created during processing.' => 'Մշակման ընթացքում ստեղծվում է մանրապատկեր:',
  'Complete the import details first.' => 'Նախ լրացրեք ներմուծման մանրամասները:',
  'Import source' => 'Ներմուծման աղբյուր',
  'Import summary' => 'Ներմուծման ամփոփագիր',
  'Source URL' => 'Աղբյուրի URL',
  'Video imported' => 'Տեսանյութը ներմուծված է',
  'Your video was imported and processing has started.' => 'Ձեր տեսանյութը ներմուծվել է, և մշակումը սկսվել է:',
  'Import Video' => 'Տեսանյութի ներմուծում',
  'Import a public video URL, customize its details, and publish it through the normal processing pipeline.' => 'Ներմուծեք հանրային տեսանյութի URL, հարմարեցրեք դրա մանրամասները և հրապարակեք այն սովորական մշակման խողովակաշարի միջոցով:',
  'Video Import' => 'Տեսանյութի ներմուծում',
  'Enable importing videos from supported external providers.' => 'Միացնել տեսանյութերի ներմուծումը աջակցվող արտաքին մատակարարներից:',
  'Downloader Command' => 'Ներբեռնիչի հրաման',
  'YouTube Data API key' => 'YouTube Data API բանալի',
  'Vimeo access token' => 'Vimeo մուտքի նշան',
  'Dailymotion API key' => 'Dailymotion API բանալի',
  'API Key' => 'API բանալի',
  'Not required' => 'Չի պահանջվում',
  'Save Import Settings' => 'Պահպանեք ներմուծման կարգավորումները',
  'Video import settings saved.' => 'Տեսանյութի ներմուծման կարգավորումները պահպանված են:',
  'Video import started.' => 'Տեսանյութի ներմուծումը սկսվեց:',
  'This video import provider is disabled.' => 'Տեսանյութերի ներմուծման այս մատակարարն անջատված է:',
  'Video import provider is disabled.' => 'Տեսանյութերի ներմուծման մատակարարն անջատված է:',
  'Direct imports must use a supported video file URL.' => 'Ուղղակի ներմուծումները պետք է օգտագործեն աջակցվող վիդեո ֆայլի URL:',
  'Cannot open remote video URL.' => 'Հնարավոր չէ բացել հեռակա տեսանյութի URL-ը:',
  'Cannot prepare imported video file.' => 'Հնարավոր չէ պատրաստել ներմուծված վիդեո ֆայլ:',
  'Cannot read remote video file.' => 'Հնարավոր չէ կարդալ հեռակա վիդեո ֆայլը:',
  'Imported video exceeds the maximum upload size.' => 'Ներմուծված տեսանյութը գերազանցում է վերբեռնման առավելագույն չափը:',
  'Remote video file is empty.' => 'Հեռավոր վիդեո ֆայլը դատարկ է:',
  'Video import downloader command is not configured.' => 'Տեսանյութերի ներմուծման ներբեռնիչ հրամանը կազմաձևված չէ:',
  'Downloader did not create an importable video file.' => 'Ներբեռնիչը չի ստեղծել ներմուծվող վիդեո ֆայլ:',
  'Import URL is invalid.' => 'Ներմուծման URL-ն անվավեր է:',
  'Import URL must use HTTP or HTTPS.' => 'Ներմուծման URL-ը պետք է օգտագործի HTTP կամ HTTPS:',
  'Import URL host is invalid.' => 'URL-ի ներմուծման հոսթն անվավեր է:',
  'Import URL does not match the selected provider.' => 'Ներմուծման URL-ը չի համապատասխանում ընտրված մատակարարին:',
  'Import URL host cannot be resolved.' => 'URL-ի ներմուծման հոսթինգը չի կարող լուծվել:',
  'Import URL must resolve to a public host.' => 'Ներմուծման URL-ը պետք է լուծվի հանրային հոսթին:',
  'Unknown video import provider.' => 'Տեսանյութերի ներմուծման անհայտ մատակարար:',
  'Saves a public video file URL and plays it from the original URL.' => 'Պահում է հանրային վիդեո ֆայլի URL-ը և նվագարկում այն ​​սկզբնական URL-ից:',
  'Fetches YouTube details and plays with the YouTube embed player.' => 'Վերցնում է YouTube-ի մանրամասները և խաղում YouTube-ի ներդրման նվագարկչի հետ:',
  'Fetches Vimeo details and plays with the Vimeo embed player.' => 'Վերցնում է Vimeo-ի մանրամասները և խաղում Vimeo ներկառուցված նվագարկչի հետ:',
  'Fetches Dailymotion details and plays with the Dailymotion embed player.' => 'Ներբեռնում է Dailymotion-ի մանրամասները և խաղում Dailymotion ներկառուցված նվագարկչի հետ:',
  'Select an enabled service and paste a public video URL. PlayHub will fetch the details and play it from the original provider.' => 'Ընտրեք միացված ծառայություն և տեղադրեք հանրային տեսանյութի URL: PlayHub-ը կվերցնի մանրամասները և կցուցադրի դրանք սկզբնական մատակարարից:',
  'Fetching...' => 'Բերվում է...',
  'Fetch details' => 'Վերցրեք մանրամասները',
  'Unable to fetch provider details.' => 'Հնարավոր չէ բեռնել մատակարարի տվյալները:',
  'Saving provider video' => 'Պահպանվում է մատակարարի տեսանյութը',
  'Fetched from provider' => 'Վերցված է մատակարարից',
  'Fetch details to preview' => 'Ստացեք մանրամասներ՝ նախադիտելու համար',
  'Provider thumbnails are saved as remote metadata.' => 'Մատակարարի մանրապատկերները պահվում են որպես հեռավոր մետատվյալներ:',
  'External provider video' => 'Արտաքին մատակարարի տեսանյութ',
  'Video import saved.' => 'Տեսանյութի ներմուծումը պահված է:',
  'Could not read the provider video ID from this URL.' => 'Չհաջողվեց կարդալ մատակարարի տեսանյութի ID-ն այս URL-ից:',
  'Import a public video URL, fetch provider details, and publish it with external playback.' => 'Ներմուծեք հանրային տեսանյութի URL, առբերեք մատակարարի մանրամասները և հրապարակեք այն արտաքին նվագարկումով:',
  'Paste a video import URL' => 'Տեղադրեք տեսանյութի ներմուծման URL',
