  'Webcam preview works locally. Public broadcasting requires the LiveKit media engine.' => 'Վեբ-տեսախցիկի նախադիտումն աշխատում է տեղում: Հանրային հեռարձակման համար անհրաժեշտ է LiveKit մեդիա շարժիչ:',
